// Good: Validate and sanitize input before using it in URL construction
import java.net.URL;
import java.net.MalformedURLException;

public class GoodExample {
    public static void main(String[] args) {
        String userInput = "http://internal-service:8080/admin"; // Malicious input
        try {
            // Validate the URL to prevent SSRF attacks
            if (isValidUrl(userInput)) {
                URL url = new URL(userInput);
                System.out.println("Loading URL: " + url.toString());
            } else {
                System.out.println("Invalid or potentially malicious URL.");
            }
        } catch (MalformedURLException e) {
            e.printStackTrace();
        }
    }

    // Helper method to validate URL format and prevent SSRF
    private static boolean isValidUrl(String input) {
        // Basic validation: check if the URL starts with http:// or https://
        return input != null && input.startsWith("http://") && !input.contains("localhost") && !input.contains("internal");
    }
}
